/// Read the 16-byte `origin_id` into `out_16`. NULL-safe.
///
/// # Safety
/// `p` must be either NULL or a valid pointer to a `pms_pulse`.
/// `out_16` must point to at least 16 writable bytes (or be NULL).
#[no_mangle]
pub unsafe extern "C" fn pms_pulse_get_origin_id(p: *const pms_pulse, out_16: *mut c_uchar) {
    if p.is_null() || out_16.is_null() {
        return;
    }
    // SAFETY: `p` was checked non-null above; per the function contract it points
    // to a live `pms_pulse` for the duration of this call.
    let inner = read_inner(unsafe { &*p });
    // SAFETY: out_16 was checked non-null; copying exactly 16 bytes.
    unsafe {
        ptr::copy_nonoverlapping(inner.origin_id.as_ptr(), out_16, 16);
    }
}

/// Write 16 bytes of `id_16` into the Pulse's `origin_id` field. NULL-safe.
///
/// # Safety
/// `p` must be either NULL or a valid pointer to a `pms_pulse`.
/// `id_16` must point to at least 16 readable bytes (or be NULL).
#[no_mangle]
pub unsafe extern "C" fn pms_pulse_set_origin_id(p: *mut pms_pulse, id_16: *const c_uchar) {
    if p.is_null() || id_16.is_null() {
        return;
    }
    // SAFETY: `p` was checked non-null above; per the function contract it points
    // to a live `pms_pulse` that no other reference touches during this call.
    let p = unsafe { &mut *p };
    let mut inner = read_inner(p);
    // SAFETY: id_16 was checked non-null; copying exactly 16 bytes.
    unsafe {
        ptr::copy_nonoverlapping(id_16, inner.origin_id.as_mut_ptr(), 16);
    }
    write_back(p, &inner);
}

/// Read the 16-byte `envelope_ref` into `out_16`: the content id of the
/// envelope the Pulse names, all zeros when it names none. NULL-safe.
///
/// # Safety
/// `p` must be either NULL or a valid pointer to a `pms_pulse`.
/// `out_16` must point to at least 16 writable bytes (or be NULL).
#[no_mangle]
pub unsafe extern "C" fn pms_pulse_get_envelope_ref(p: *const pms_pulse, out_16: *mut c_uchar) {
    if p.is_null() || out_16.is_null() {
        return;
    }
    // SAFETY: `p` was checked non-null above; per the function contract it points
    // to a live `pms_pulse` for the duration of this call.
    let inner = read_inner(unsafe { &*p });
    // SAFETY: out_16 was checked non-null; copying exactly 16 bytes.
    unsafe {
        ptr::copy_nonoverlapping(inner.envelope_ref.as_ptr(), out_16, 16);
    }
}

/// Write the 16 bytes of `ref_16` into the Pulse's `envelope_ref`, naming
/// the envelope of that content id; all zeros names none. The instruction
/// is left as it is; by convention a Pulse naming an envelope is DATA
/// (0x0010). NULL-safe.
///
/// # Safety
/// `p` must be either NULL or a valid pointer to a `pms_pulse`.
/// `ref_16` must point to at least 16 readable bytes (or be NULL).
#[no_mangle]
pub unsafe extern "C" fn pms_pulse_set_envelope_ref(p: *mut pms_pulse, ref_16: *const c_uchar) {
    if p.is_null() || ref_16.is_null() {
        return;
    }
    // SAFETY: `p` was checked non-null above; per the function contract it points
    // to a live `pms_pulse` that no other reference touches during this call.
    let p = unsafe { &mut *p };
    let mut inner = read_inner(p);
    let mut id = [0u8; 16];
    // SAFETY: ref_16 was checked non-null; copying exactly 16 bytes.
    unsafe {
        ptr::copy_nonoverlapping(ref_16, id.as_mut_ptr(), 16);
    }
    inner.set_envelope_id(&PulseEnvelopeId(id));
    write_back(p, &inner);
}

// ──────────────────────────── Sender ─────────────────────────────────

/// Opaque sender handle. Allocate with `pms_sender_bind`, release with
/// `pms_sender_destroy`.
pub struct pms_sender {
    inner: RustSender,
}

/// Bind a sender socket to `local_addr` (e.g. `"127.0.0.1:0"` to let
/// the OS pick a port). On success, `*out` holds a heap-allocated
/// handle that the caller must release via `pms_sender_destroy`.
///
/// # Safety
/// `local_addr` must be a NUL-terminated UTF-8 string. `out` must be
/// non-NULL and point to a writable `pms_sender*` slot.
#[no_mangle]
pub unsafe extern "C" fn pms_sender_bind(
    local_addr: *const c_char,
    out: *mut *mut pms_sender,
) -> pms_status {
    if local_addr.is_null() || out.is_null() {
        set_last_error("pms_sender_bind: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: this function's contract makes `local_addr` a NUL-terminated string
    // that outlives the call, and the `&str` is used only within it.
    let addr = match unsafe { c_str_to_str(local_addr) } {
        Ok(s) => s,
        Err(status) => return status,
    };
    match RustSender::bind(addr) {
        Ok(s) => {
            let boxed = Box::new(pms_sender { inner: s });
            // SAFETY: caller asserted `out` is a writable slot.
            unsafe { *out = Box::into_raw(boxed) };
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            set_last_error(format!("bind '{addr}' failed: {e}"));
            map_sender_err(&e)
        }
    }
}

/// Set the default destination for `pms_sender_send`.
///
/// # Safety
/// `s` must be a valid handle obtained from `pms_sender_bind`.
/// `dest` must be a NUL-terminated UTF-8 string.
#[no_mangle]
pub unsafe extern "C" fn pms_sender_connect(
    s: *mut pms_sender,
    dest: *const c_char,
) -> pms_status {
    if s.is_null() || dest.is_null() {
        set_last_error("pms_sender_connect: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: this function's contract makes `dest` a NUL-terminated string
    // that outlives the call, and the `&str` is used only within it.
    let addr = match unsafe { c_str_to_str(dest) } {
        Ok(s) => s,
        Err(status) => return status,
    };
    // SAFETY: caller asserts `s` is a valid handle from `pms_sender_bind`.
    let inner = unsafe { &mut (*s).inner };
    match inner.connect(addr) {
        Ok(()) => {
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            set_last_error(format!("connect '{addr}' failed: {e}"));
            map_sender_err(&e)
        }
    }
}

/// Send one frame to the connected destination. `out_seq` may be NULL
/// if the caller does not need the wire-stamped sequence number.
///
/// # Safety
/// `s` and `pulse` must be valid pointers. `envelope` may be NULL only
/// if `envelope_len == 0`. `out_seq` is optional (may be NULL).
#[no_mangle]
pub unsafe extern "C" fn pms_sender_send(
    s: *mut pms_sender,
    send_ns: u64,
    pulse: *const pms_pulse,
    envelope: *const c_uchar,
    envelope_len: usize,
    out_seq: *mut u64,
) -> pms_status {
    if s.is_null() || pulse.is_null() {
        set_last_error("pms_sender_send: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    if envelope_len > 0 && envelope.is_null() {
        set_last_error("pms_sender_send: NULL envelope with non-zero length");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: handles validated above.
    let inner = unsafe { &mut (*s).inner };
    // SAFETY: `pulse` was checked non-null and points to a live
    // `pms_pulse`, whose alignment is 1, so the reference is aligned
    // wherever the caller put it; `read_inner` copies its bytes into an
    // aligned Rust Pulse rather than reinterpreting them.
    let pulse_owned = read_inner(unsafe { &*pulse });
    let env: &[u8] = if envelope_len == 0 {
        &[]
    } else {
        // SAFETY: caller asserts `envelope` points to `envelope_len`
        // valid readable bytes.
        unsafe { std::slice::from_raw_parts(envelope, envelope_len) }
    };
    match inner.send(send_ns, &pulse_owned, env) {
        Ok(seq) => {
            if !out_seq.is_null() {
                // SAFETY: caller passed a writable pointer.
                unsafe { *out_seq = seq };
            }
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            set_last_error(format!("send failed: {e}"));
            map_sender_err(&e)
        }
    }
}

/// Send one frame to `dest`, overriding any default destination.
///
/// # Safety
/// `s`, `pulse`, and `dest` must be non-NULL and valid. `envelope` may
/// be NULL only if `envelope_len == 0`. `out_seq` is optional.
#[no_mangle]
pub unsafe extern "C" fn pms_sender_send_to(
    s: *mut pms_sender,
    send_ns: u64,
    pulse: *const pms_pulse,
    envelope: *const c_uchar,
    envelope_len: usize,
    dest: *const c_char,
    out_seq: *mut u64,
) -> pms_status {
    if s.is_null() || pulse.is_null() || dest.is_null() {
        set_last_error("pms_sender_send_to: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    if envelope_len > 0 && envelope.is_null() {
        set_last_error("pms_sender_send_to: NULL envelope with non-zero length");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: this function's contract makes `dest` a NUL-terminated string
    // that outlives the call, and the `&str` is used only within it.
    let dest_str = match unsafe { c_str_to_str(dest) } {
        Ok(s) => s,
        Err(status) => return status,
    };
    let addr: SocketAddr = match dest_str.parse() {
        Ok(a) => a,
        Err(e) => {
            set_last_error(format!("invalid socket address '{dest_str}': {e}"));
            return pms_status::PmsErrInvalidArg;
        }
    };
    // SAFETY: handles validated above.
    let inner = unsafe { &mut (*s).inner };
    // SAFETY: as in `pms_sender_send`: non-null, live, alignment 1.
    let pulse_owned = read_inner(unsafe { &*pulse });
    let env: &[u8] = if envelope_len == 0 {
        &[]
    } else {
        // SAFETY: caller asserts `envelope` is valid.
        unsafe { std::slice::from_raw_parts(envelope, envelope_len) }
    };
    match inner.send_to(send_ns, &pulse_owned, env, addr) {
        Ok(seq) => {
            if !out_seq.is_null() {
                // SAFETY: caller passed a writable pointer.
                unsafe { *out_seq = seq };
            }
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            set_last_error(format!("send_to '{addr}' failed: {e}"));
            map_sender_err(&e)
        }
    }
}

/// Write the sender's local socket address (e.g. "127.0.0.1:43912") as
/// a NUL-terminated string into `out_buf`. Truncates if `out_buf_len`
/// is too small (always NUL-terminates if `out_buf_len > 0`).
///
/// # Safety
/// `s` must be a valid handle. `out_buf` must point to `out_buf_len`
/// writable bytes (or be NULL with `out_buf_len == 0`).
#[no_mangle]
pub unsafe extern "C" fn pms_sender_local_addr(
    s: *const pms_sender,
    out_buf: *mut c_char,
    out_buf_len: usize,
) -> pms_status {
    if s.is_null() {
        set_last_error("pms_sender_local_addr: NULL handle");
        return pms_status::PmsErrInvalidArg;
    }
    if out_buf_len > 0 && out_buf.is_null() {
        set_last_error("pms_sender_local_addr: NULL out_buf with non-zero len");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: handle validated.
    let inner = unsafe { &(*s).inner };
    match inner.local_addr() {
        Ok(addr) => {
            // SAFETY: out_buf validated above for non-zero len.
            unsafe { write_str_to_c_buf(&addr.to_string(), out_buf, out_buf_len) };
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            set_last_error(format!("local_addr failed: {e}"));
            pms_status::PmsErrIo
        }
    }
}

/// Release a sender handle obtained from `pms_sender_bind`. NULL-safe.
///
/// # Safety
/// `s` must either be NULL or a handle previously returned by
/// `pms_sender_bind` and not already destroyed.
#[no_mangle]
pub unsafe extern "C" fn pms_sender_destroy(s: *mut pms_sender) {
    if s.is_null() {
        return;
    }
    // SAFETY: caller asserts `s` is a live handle from
    // `pms_sender_bind`. We reconstruct the Box and let it drop.
    drop(unsafe { Box::from_raw(s) });
}

// ───────────────────────────── Receiver ──────────────────────────────

/// Opaque receiver handle. Allocate with `pms_receiver_bind`, release
/// with `pms_receiver_destroy`.
pub struct pms_receiver {
    inner: RustReceiver,
}

/// Bind a receiver socket to `local_addr`.
///
/// # Safety
/// `local_addr` must be NUL-terminated UTF-8. `out` must be non-NULL.
#[no_mangle]
pub unsafe extern "C" fn pms_receiver_bind(
    local_addr: *const c_char,
    out: *mut *mut pms_receiver,
) -> pms_status {
    if local_addr.is_null() || out.is_null() {
        set_last_error("pms_receiver_bind: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: this function's contract makes `local_addr` a NUL-terminated string
    // that outlives the call, and the `&str` is used only within it.
    let addr = match unsafe { c_str_to_str(local_addr) } {
        Ok(s) => s,
        Err(status) => return status,
    };
    match RustReceiver::bind(addr) {
        Ok(r) => {
            let boxed = Box::new(pms_receiver { inner: r });
            // SAFETY: caller asserted `out` is writable.
            unsafe { *out = Box::into_raw(boxed) };
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            set_last_error(format!("bind '{addr}' failed: {e}"));
            pms_status::PmsErrIo
        }
    }
}

/// Set the receiver's read timeout in milliseconds. Pass `0` to clear
/// the timeout (block indefinitely on `recv_into`).
///
/// # Safety
/// `r` must be a valid handle from `pms_receiver_bind`.
#[no_mangle]
pub unsafe extern "C" fn pms_receiver_set_read_timeout_ms(
    r: *mut pms_receiver,
    millis: u64,
) -> pms_status {
    if r.is_null() {
        set_last_error("pms_receiver_set_read_timeout_ms: NULL handle");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: handle validated.
    let inner = unsafe { &(*r).inner };
    let dur = if millis == 0 {
        None
    } else {
        Some(Duration::from_millis(millis))
    };
    match inner.set_read_timeout(dur) {
        Ok(()) => {
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            set_last_error(format!("set_read_timeout failed: {e}"));
            pms_status::PmsErrIo
        }
    }
}

/// Receive one frame, writing the envelope into `envelope_buf` in
/// place. On success, `*out_env_len` is the actual envelope length;
/// `envelope_buf[..*out_env_len]` carries the bytes. Optional outputs
/// (`out_seq`, `out_send_ns`, `out_peer`) may be NULL.
///
/// Returns `PMS_ERR_TIMEOUT` if the configured read timeout elapses,
/// `PMS_ERR_BUFFER_TOO_SMALL` if `envelope_buf_len` is smaller than
/// the incoming envelope (the frame is consumed in that case),
/// `PMS_ERR_DECODE` for wire-format failures.
///
/// # Safety
/// `r`, `envelope_buf`, `out_pulse`, and `out_env_len` must be non-NULL
/// and point to writable memory of the appropriate size. `out_peer`
/// may be NULL with `out_peer_len == 0`.
#[no_mangle]
pub unsafe extern "C" fn pms_receiver_recv_into(
    r: *mut pms_receiver,
    envelope_buf: *mut c_uchar,
    envelope_buf_len: usize,
    out_pulse: *mut pms_pulse,
    out_env_len: *mut usize,
    out_seq: *mut u64,
    out_send_ns: *mut u64,
    out_peer: *mut c_char,
    out_peer_len: usize,
) -> pms_status {
    if r.is_null()
        || envelope_buf.is_null()
        || out_pulse.is_null()
        || out_env_len.is_null()
    {
        set_last_error("pms_receiver_recv_into: NULL required argument");
        return pms_status::PmsErrInvalidArg;
    }
    if out_peer_len > 0 && out_peer.is_null() {
        set_last_error("pms_receiver_recv_into: NULL out_peer with non-zero len");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: handle and buffer validated.
    let inner = unsafe { &mut (*r).inner };
    let buf = unsafe { std::slice::from_raw_parts_mut(envelope_buf, envelope_buf_len) };

    match inner.recv_into(buf) {
        Ok((pulse, env_len, meta)) => {
            // Write Pulse bytes verbatim.
            // SAFETY: out_pulse was checked non-null above and, per the
            // contract, points to a writable `pms_pulse`: 128 bytes with
            // alignment 1, not the Rust Pulse's 64, so it is only ever
            // written as bytes, which fit it wherever the caller put it.
            unsafe {
                let bytes = pulse.as_bytes();
                ptr::copy_nonoverlapping(
                    bytes.as_ptr(),
                    (*out_pulse).bytes.as_mut_ptr(),
                    128,
                );
            }
            // SAFETY: out_env_len validated.
            unsafe { *out_env_len = env_len };
            if !out_seq.is_null() {
                // SAFETY: caller-supplied writable pointer.
                unsafe { *out_seq = meta.seq };
            }
            if !out_send_ns.is_null() {
                // SAFETY: caller-supplied writable pointer.
                unsafe { *out_send_ns = meta.send_ns };
            }
            if !out_peer.is_null() && out_peer_len > 0 {
                // SAFETY: out_peer / out_peer_len validated.
                unsafe { write_str_to_c_buf(&meta.peer.to_string(), out_peer, out_peer_len) };
            }
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            if e.is_timeout() {
                set_last_error(format!("recv timeout: {e}"));
                return pms_status::PmsErrTimeout;
            }
            let code = match &e {
                RustReceiverError::Io(_) => pms_status::PmsErrIo,
                RustReceiverError::Decode(_) => pms_status::PmsErrDecode,
                RustReceiverError::BufferTooSmall { .. } => pms_status::PmsErrBufferTooSmall,
                _ => pms_status::PmsErrInternal,
            };
            set_last_error(format!("recv failed: {e}"));
            code
        }
    }
}

/// Write the receiver's local socket address as a NUL-terminated
/// string into `out_buf`. Truncates if `out_buf_len` is too small.
///
/// # Safety
/// `r` must be a valid handle. `out_buf` must point to `out_buf_len`
/// writable bytes (or be NULL with `out_buf_len == 0`).
#[no_mangle]
pub unsafe extern "C" fn pms_receiver_local_addr(
    r: *const pms_receiver,
    out_buf: *mut c_char,
    out_buf_len: usize,
) -> pms_status {
    if r.is_null() {
        set_last_error("pms_receiver_local_addr: NULL handle");
        return pms_status::PmsErrInvalidArg;
    }
    if out_buf_len > 0 && out_buf.is_null() {
        set_last_error("pms_receiver_local_addr: NULL out_buf with non-zero len");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: handle validated.
    let inner = unsafe { &(*r).inner };
    match inner.local_addr() {
        Ok(addr) => {
            // SAFETY: out_buf validated.
            unsafe { write_str_to_c_buf(&addr.to_string(), out_buf, out_buf_len) };
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            set_last_error(format!("local_addr failed: {e}"));
            pms_status::PmsErrIo
        }
    }
}

/// Release a receiver handle obtained from `pms_receiver_bind`.
/// NULL-safe.
///
/// # Safety
/// `r` must either be NULL or a handle previously returned by
/// `pms_receiver_bind` and not already destroyed.
#[no_mangle]
pub unsafe extern "C" fn pms_receiver_destroy(r: *mut pms_receiver) {
    if r.is_null() {
        return;
    }
    // SAFETY: caller asserts `r` is a live handle.
    drop(unsafe { Box::from_raw(r) });
}

// ───────────────────────────── Pair ──────────────────────────────────

/// Bind one UDP socket at `local_addr` and return a sender and a receiver
/// that share it, so datagrams go out from the port replies come back to.
/// A peer behind a home router (NAT) needs this: the router opens a path
/// back only to the port a datagram left from, and often only for replies
/// from the address it went to, so a program that sends and receives on
/// two sockets never hears its replies. A peer that answers replies with
/// its own pair's sender (`pms_sender_send_to`) to the `out_peer` its
/// receiver reported.
///
/// On success `*out_sender` and `*out_receiver` hold handles the caller
/// releases with `pms_sender_destroy` and `pms_receiver_destroy`, in
/// either order; the socket closes with the second. On failure neither is
/// written.
///
/// # Safety
/// `local_addr` must be a NUL-terminated UTF-8 string. `out_sender` and
/// `out_receiver` must be non-NULL and point to writable handle slots.
#[no_mangle]
pub unsafe extern "C" fn pms_bind_pair(
    local_addr: *const c_char,
    out_sender: *mut *mut pms_sender,
    out_receiver: *mut *mut pms_receiver,
) -> pms_status {
    if local_addr.is_null() || out_sender.is_null() || out_receiver.is_null() {
        set_last_error("pms_bind_pair: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: this function's contract makes `local_addr` a NUL-terminated string
    // that outlives the call, and the `&str` is used only within it.
    let addr = match unsafe { c_str_to_str(local_addr) } {
        Ok(s) => s,
        Err(status) => return status,
    };
    let socket = match std::net::UdpSocket::bind(addr) {
        Ok(socket) => socket,
        Err(e) => {
            set_last_error(format!("bind '{addr}' failed: {e}"));
            return pms_status::PmsErrIo;
        }
    };
    let clone = match socket.try_clone() {
        Ok(clone) => clone,
        Err(e) => {
            set_last_error(format!("bind '{addr}': cloning the socket failed: {e}"));
            return pms_status::PmsErrIo;
        }
    };
    let sender = Box::new(pms_sender {
        inner: RustSender::from_socket(clone),
    });
    let receiver = Box::new(pms_receiver {
        inner: RustReceiver::from_socket(socket),
    });
    // SAFETY: the caller asserted both slots are writable.
    unsafe {
        *out_sender = Box::into_raw(sender);
        *out_receiver = Box::into_raw(receiver);
    }
    clear_last_error();
    pms_status::PmsOk
}

// ───────────────────────────── Channel ───────────────────────────────
//
// One-way, lossless, in-order messages between processes on one host,
// over a Pulse ring and an envelope store in shared memory: the Python
// binding's `Channel` (bindings/python/src/channel.rs), whose
// names, envelopes, framing and waits these mirror, so that a C end and a
// Python end share one channel.
//
// A channel is a ring named `name` and a store named `name + "-e"`. The
// writer stores each message as one `PulseEnvelope` and publishes a Data
// pulse naming its store cursor and id; the reader walks the ring's
// positions in order and fetches each envelope a pulse names. A message's
// payload is a list of frames, `count:u32_le`, then for each frame
// `len:u32_le ‖ bytes`; this binding sends and receives one-frame messages.

/// The type name every channel envelope carries.
const CHANNEL_TYPE_NAME: &str = "pulse/channel";

/// Longest POSIX shared-memory name, leading slash included, that every
/// supported host accepts: macOS's `PSHMNAMLEN` is 31.
const MAX_SHM_NAME: usize = 31;

/// Suffix of the store's name after the ring's.
const STORE_SUFFIX: &str = "-e";

/// How long `pms_channel_open` retries while the writer has not created
/// the channel: the Python binding's default.
const OPEN_WAIT: Duration = Duration::from_secs(10);

/// How long `pms_channel_send` waits for the reader to leave room: the
/// Python binding's default.
const SEND_WAIT: Duration = Duration::from_secs(5);

/// How long a waiter spins before it starts to sleep.
const SPIN: Duration = Duration::from_micros(50);
/// First sleep after the spin; each later one doubles, up to [`MAX_SLEEP`].
const FIRST_SLEEP: Duration = Duration::from_micros(20);
/// Longest single sleep of a waiter.
const MAX_SLEEP: Duration = Duration::from_millis(1);

/// The `timeout_ms` that makes `pms_channel_recv` wait without limit.
#[no_mangle]
pub static PMS_CHANNEL_WAIT_FOREVER: u32 = u32::MAX;

/// A wait that spins for [`SPIN`], then sleeps from [`FIRST_SLEEP`] doubling
/// to [`MAX_SLEEP`], never past its deadline.
struct Backoff {
    spin_until: Instant,
    sleep: Duration,
    deadline: Option<Instant>,
}

impl Backoff {
    fn new(timeout: Option<Duration>) -> Self {
        let now = Instant::now();
        Self {
            spin_until: now + SPIN,
            sleep: FIRST_SLEEP,
            deadline: timeout.and_then(|t| now.checked_add(t)),
        }
    }

    /// Wait one step; `false` once the deadline has passed.
    fn step(&mut self) -> bool {
        let now = Instant::now();
        if let Some(deadline) = self.deadline {
            if now >= deadline {
                return false;
            }
        }
        if now < self.spin_until {
            std::hint::spin_loop();
            return true;
        }
        let nap = match self.deadline {
            Some(deadline) => self.sleep.min(deadline - now),
            None => self.sleep,
        };
        std::thread::sleep(nap);
        self.sleep = (self.sleep * 2).min(MAX_SLEEP);
        true
    }
}

/// What went wrong in a channel operation, reported as a status and the
/// message `pms_last_error` returns.
enum ChannelError {
    BadName(String),
    TooLarge { actual: usize },
    Stalled { in_flight: u64, waited: Duration },
    TimedOut,
    Closed,
    BufferTooSmall { needed: usize, cap: usize },
    NotOneFrame { count: usize },
    Lost { position: u64, next: u64 },
    NotStored { position: u64, cursor: Option<u64> },
    Malformed(String),
    Ring(RingError),
    Store(EnvelopeStoreError),
    OpenTimedOut { waited: Duration, last: String },
}

impl ChannelError {
    fn status(&self) -> pms_status {
        match self {
            Self::BadName(_) => pms_status::PmsErrInvalidArg,
            Self::TooLarge { .. } => pms_status::PmsErrEnvelopeTooLarge,
            Self::Stalled { .. } | Self::TimedOut | Self::OpenTimedOut { .. } => {
                pms_status::PmsErrTimeout
            }
            Self::Closed => pms_status::PmsErrClosed,
            Self::BufferTooSmall { .. } => pms_status::PmsErrBufferTooSmall,
            Self::NotOneFrame { .. } | Self::Malformed(_) => pms_status::PmsErrDecode,
            Self::Lost { .. } | Self::NotStored { .. } => pms_status::PmsErrInternal,
            Self::Ring(RingError::InvalidName | RingError::InvalidCapacity { .. })
            | Self::Ring(RingError::NameTooLong { .. })
            | Self::Store(
                EnvelopeStoreError::InvalidName | EnvelopeStoreError::InvalidCapacity { .. },
            ) => pms_status::PmsErrInvalidArg,
            Self::Ring(_) | Self::Store(_) => pms_status::PmsErrIo,
        }
    }

    /// Set `pms_last_error` to `what: <this error>` and return its status.
    fn report(self, what: &str) -> pms_status {
        let status = self.status();
        set_last_error(format!("{what}: {self}"));
        status
    }
}

impl std::fmt::Display for ChannelError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        match self {
            Self::BadName(why) => f.write_str(why),
            Self::TooLarge { actual } => write!(
                f,
                "message envelope is {actual} bytes; a channel message is limited to the \
                 envelope store's {MAX_ENTRY_SIZE}-byte (64 KB) entry, framing included \
                 (pms_channel_max_len() bytes of data). Nothing was sent"
            ),
            Self::Stalled { in_flight, waited } => write!(
                f,
                "waited {waited:?} with {in_flight} messages unread; the reader stopped, died \
                 or never opened the channel. Nothing was sent"
            ),
            Self::TimedOut => f.write_str("no message came in time"),
            Self::Closed => f.write_str("the writer closed the channel; every message was read"),
            Self::BufferTooSmall { needed, cap } => write!(
                f,
                "buffer too small: the message is {needed} bytes and the buffer {cap}; it stays \
                 unread"
            ),
            Self::NotOneFrame { count } => write!(
                f,
                "the message has {count} frames, and pms_channel_recv takes one-frame messages \
                 only; it was consumed"
            ),
            Self::Lost { position, next } => write!(
                f,
                "lost positions {position}..{next}: the ring was overwritten before they were \
                 read, which a channel with one writer and one reader never does"
            ),
            Self::NotStored { position, cursor } => write!(
                f,
                "position {position} names an envelope not in the store at cursor {cursor:?}: \
                 its slot was reused before it was read"
            ),
            Self::Malformed(why) => write!(f, "malformed channel message: {why}"),
            Self::Ring(e) => write!(f, "ring: {e}"),
            Self::Store(e) => write!(f, "envelope store: {e}"),
            Self::OpenTimedOut { waited, last } => {
                write!(f, "found no channel within {waited:?}: {last}")
            }
        }
    }
}

/// The ring and store names for a channel `name`: a leading slash is added
/// when missing, and the longer of the two must fit [`MAX_SHM_NAME`].
fn shm_names(name: &str) -> Result<(String, String), ChannelError> {
    let ring = if name.starts_with('/') {
        name.to_owned()
    } else {
        format!("/{name}")
    };
    if ring.len() < 2 || ring[1..].contains('/') {
        return Err(ChannelError::BadName(format!(
            "channel name '{name}' must be non-empty, with no '/' after an optional leading one"
        )));
    }
    let store = format!("{ring}{STORE_SUFFIX}");
    if store.len() > MAX_SHM_NAME {
        return Err(ChannelError::BadName(format!(
            "channel name '{name}' is too long: its store's shared-memory name '{store}' is {} \
             bytes and macOS allows {MAX_SHM_NAME} (leading slash included), so a name may be at \
             most {} bytes with its leading slash",
            store.len(),
            MAX_SHM_NAME - STORE_SUFFIX.len()
        )));
    }
    Ok((ring, store))
}

/// A random 16-byte origin for one writer, never all zeros, made as the hub
/// runtime makes an instance id.
fn new_origin() -> [u8; 16] {
    use std::hash::BuildHasher;
    use std::sync::atomic::{AtomicU64, Ordering};
    static MADE: AtomicU64 = AtomicU64::new(0);
    let made = MADE.fetch_add(1, Ordering::Relaxed);
    let pid = std::process::id();
    let mut id = [0u8; 16];
    for (half, bytes) in (0u8..).zip(id.chunks_exact_mut(8)) {
        let hash = std::collections::hash_map::RandomState::new().hash_one((pid, made, half));
        bytes.copy_from_slice(&hash.to_le_bytes());
    }
    if id == [0u8; 16] {
        id[0] = 1;
    }
    id
}

/// Bytes of a channel envelope's canonical encoding besides its payload.
fn envelope_overhead() -> usize {
    PulseEnvelope::typed(CHANNEL_TYPE_NAME, Vec::new()).canonical_size()
}

/// Largest frame of a one-frame message: the store's entry, less the
/// envelope around the payload and the payload's count and length.
fn max_frame() -> usize {
    MAX_ENTRY_SIZE - envelope_overhead() - 8
}

/// Split a framed payload into its frames.
fn decode_frames(payload: &[u8]) -> Result<Vec<&[u8]>, ChannelError> {
    let take_u32 = |at: usize| -> Result<usize, ChannelError> {
        payload
            .get(at..at + 4)
            .map(|b| u32::from_le_bytes([b[0], b[1], b[2], b[3]]) as usize)
            .ok_or_else(|| ChannelError::Malformed(format!("truncated at byte {at}")))
    };
    let count = take_u32(0)?;
    let mut at = 4;
    let mut frames = Vec::with_capacity(count.min(payload.len() / 4));
    for _ in 0..count {
        let len = take_u32(at)?;
        at += 4;
        let frame = payload
            .get(at..at + len)
            .ok_or_else(|| ChannelError::Malformed(format!("frame overruns at byte {at}")))?;
        frames.push(frame);
        at += len;
    }
    if at != payload.len() {
        return Err(ChannelError::Malformed(format!(
            "{} bytes after the last frame",
            payload.len() - at
        )));
    }
    Ok(frames)
}

/// The open ends of a channel.
struct Ends {
    ring: PulseRing,
    store: EnvelopeStore,
    writer: bool,
    /// The reader's next position to read.
    next: u64,
    /// The writer's most messages unread at once: the ring's capacity or the
    /// store's slots, whichever is fewer, so neither is overwritten unread.
    window: u64,
    /// The writer's origin, stamped on its pulses and envelopes.
    origin: [u8; 16],
}

impl Ends {
    /// Store `frame` as a one-frame message's envelope and publish the Data
    /// pulse naming it, once the reader has left room, waiting at most
    /// `timeout`.
    fn send(&mut self, frame: &[u8], timeout: Duration) -> Result<(), ChannelError> {
        if frame.len() > max_frame() {
            return Err(ChannelError::TooLarge {
                actual: envelope_overhead() + 8 + frame.len(),
            });
        }
        let mut payload = Vec::with_capacity(8 + frame.len());
        payload.extend_from_slice(&1u32.to_le_bytes());
        // At most `max_frame()`, so it fits a u32.
        payload.extend_from_slice(&(frame.len() as u32).to_le_bytes());
        payload.extend_from_slice(frame);

        // The hub's broadcast: an envelope stamped with the writer's origin
        // and the host's monotonic clock, stored, then a Data pulse naming
        // its store cursor and id.
        let mut envelope = PulseEnvelope::typed(CHANNEL_TYPE_NAME, payload);
        envelope.origin = self.origin;
        envelope.monotonic_nanos = pulse_wire_udp_transport::monotonic_nanos();

        // Room in the store as well as the ring: the store reuses slot
        // `cursor % slots`, so with `window` unread the next store overwrites
        // only an envelope already read.
        let started = Instant::now();
        let mut backoff = Backoff::new(Some(timeout));
        loop {
            let in_flight = self.pending();
            if in_flight < self.window {
                break;
            }
            if !backoff.step() {
                return Err(ChannelError::Stalled {
                    in_flight,
                    waited: started.elapsed(),
                });
            }
        }

        let cursor = self.store.store(&envelope).map_err(|e| match e {
            EnvelopeStoreError::EnvelopeTooLarge { actual, .. } => {
                ChannelError::TooLarge { actual }
            }
            e => ChannelError::Store(e),
        })?;
        let mut signal = RustPulse::zeroed();
        signal.set_store_cursor(cursor);
        signal.monotonic_nanos = envelope.monotonic_nanos;
        signal.origin_id = self.origin;
        signal.set_envelope_id(&envelope.id());
        // The room was waited for above, so this does not wait.
        let remaining = timeout.saturating_sub(started.elapsed());
        match self.ring.publish_blocking(&signal, remaining) {
            Ok(_) => Ok(()),
            Err(RingError::Stalled { in_flight, waited, .. }) => {
                Err(ChannelError::Stalled { in_flight, waited })
            }
            Err(e) => Err(ChannelError::Ring(e)),
        }
    }

    /// Copy the next message's frame into `out` and return its length,
    /// waiting at most `timeout` (`None`: no limit). A message longer than
    /// `out` stays unread.
    fn recv_into(
        &mut self,
        out: &mut [u8],
        timeout: Option<Duration>,
    ) -> Result<usize, ChannelError> {
        let mut backoff = Backoff::new(timeout);
        loop {
            // Read before the position: a mark seen here was set after every
            // publish, so a position still not written is never coming.
            let closed = self.ring.is_superseded();
            match self.ring.read_position_by_counter(self.next) {
                PositionRead::Pulse(pulse) => {
                    let position = self.next;
                    // The hub's delivery: the id and the store cursor the
                    // pulse names. A pulse naming no envelope is no message.
                    let Some(id) = pulse.envelope_id() else {
                        self.consume();
                        continue;
                    };
                    let cursor = pulse.store_cursor();
                    let Some(envelope) = cursor.and_then(|c| self.store.fetch_at(c, &id)) else {
                        self.consume();
                        return Err(ChannelError::NotStored { position, cursor });
                    };
                    let Some(payload) = envelope.payload().as_raw() else {
                        self.consume();
                        return Err(ChannelError::Malformed("nested payload".into()));
                    };
                    let frames = match decode_frames(payload) {
                        Ok(frames) => frames,
                        Err(e) => {
                            self.consume();
                            return Err(e);
                        }
                    };
                    let [frame] = frames[..] else {
                        self.consume();
                        return Err(ChannelError::NotOneFrame {
                            count: frames.len(),
                        });
                    };
                    // Too long for `out`: left where it is, for a call with
                    // room. The writer cannot overwrite it while it is unread.
                    let Some(room) = out.get_mut(..frame.len()) else {
                        return Err(ChannelError::BufferTooSmall {
                            needed: frame.len(),
                            cap: out.len(),
                        });
                    };
                    room.copy_from_slice(frame);
                    self.consume();
                    return Ok(frame.len());
                }
                PositionRead::NotWritten => {
                    if closed {
                        return Err(ChannelError::Closed);
                    }
                    if !backoff.step() {
                        return Err(ChannelError::TimedOut);
                    }
                }
                PositionRead::Lost { next } => {
                    return Err(ChannelError::Lost {
                        position: self.next,
                        next,
                    });
                }
            }
        }
    }

    /// Mark the reader's next position read. The writer reads the cursor
    /// only once its window looks full, so this costs it nothing until then,
    /// and frees the message's slot as soon as it is read.
    fn consume(&mut self) {
        self.next += 1;
        self.ring.advance_read_cursor(self.next);
    }

    /// Messages sent and not yet read.
    fn pending(&self) -> u64 {
        self.ring
            .cursor_position()
            .saturating_sub(self.ring.read_cursor_position())
    }
}

/// Opaque handle to one end of a shared-memory channel: one-way, lossless,
/// in-order messages between processes on one host. Make the writer end
/// with `pms_channel_create` and attach the reader end, usually in another
/// process, with `pms_channel_open`; release either with
/// `pms_channel_close`. A channel has one writer and one reader; for two
/// directions, use two channels. It is the Python binding's `Channel`, and
/// either end may be a Python one.
pub struct pms_channel {
    ends: Ends,
}

/// Create the writer end of channel `name`: a ring of `capacity` slots and
/// an envelope store of `store_slots` entries, each 64 KB of shared memory
/// (the Python binding's defaults are 4096 and 256). Objects an earlier
/// run left under either name are removed first. At most
/// `min(capacity, store_slots)` messages are unread at once;
/// `pms_channel_send` waits for the reader beyond that. On success `*out`
/// holds a handle the caller releases with `pms_channel_close`.
///
/// `name` may start with a slash and has no other; with its slash it is at
/// most 29 bytes, so the store's name, `name` and `-e`, fits macOS's
/// 31-byte limit. Returns `PMS_ERR_INVALID_ARG` for a NULL argument, a bad
/// name or a zero size, `PMS_ERR_INVALID_STRING` for a name not in UTF-8,
/// and `PMS_ERR_IO` when the shared memory cannot be made.
///
/// # Safety
/// `name` must be a NUL-terminated string. `out` must be non-NULL and
/// point to a writable `pms_channel*` slot.
#[no_mangle]
pub unsafe extern "C" fn pms_channel_create(
    name: *const c_char,
    capacity: u64,
    store_slots: usize,
    out: *mut *mut pms_channel,
) -> pms_status {
    if name.is_null() || out.is_null() {
        set_last_error("pms_channel_create: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    if capacity == 0 || store_slots == 0 {
        set_last_error("pms_channel_create: capacity and store_slots must be positive");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: this function's contract makes `name` a NUL-terminated string
    // that outlives the call, and the `&str` is used only within it.
    let name = match unsafe { c_str_to_str(name) } {
        Ok(s) => s,
        Err(status) => return status,
    };
    let created = shm_names(name).and_then(|(ring_name, store_name)| {
        let _ = PulseRing::unlink(&ring_name);
        let _ = EnvelopeStore::unlink(&store_name);
        let ring = PulseRing::create_exclusive(&ring_name, capacity).map_err(ChannelError::Ring)?;
        let store = EnvelopeStore::create_exclusive(&store_name, store_slots)
            .map_err(ChannelError::Store)?;
        Ok(Ends {
            window: capacity.min(store_slots as u64),
            ring,
            store,
            writer: true,
            next: 0,
            origin: new_origin(),
        })
    });
    match created {
        Ok(ends) => {
            // SAFETY: the caller asserted `out` is a writable slot.
            unsafe { *out = Box::into_raw(Box::new(pms_channel { ends })) };
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => e.report(&format!("pms_channel_create '{name}'")),
    }
}

/// Attach the reader end of channel `name`, retrying for up to 10 seconds
/// (the Python binding's default) while its writer has not created it. The
/// reader starts where the channel's reader last reported, so one that
/// reattaches reads no message twice. On success `*out` holds a handle the
/// caller releases with `pms_channel_close`.
///
/// Returns `PMS_ERR_TIMEOUT` if the channel never appears,
/// `PMS_ERR_INVALID_ARG` for a NULL argument or a bad name (as for
/// `pms_channel_create`), and `PMS_ERR_INVALID_STRING` for a name not in
/// UTF-8.
///
/// # Safety
/// `name` must be a NUL-terminated string. `out` must be non-NULL and
/// point to a writable `pms_channel*` slot.
#[no_mangle]
pub unsafe extern "C" fn pms_channel_open(
    name: *const c_char,
    out: *mut *mut pms_channel,
) -> pms_status {
    if name.is_null() || out.is_null() {
        set_last_error("pms_channel_open: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: this function's contract makes `name` a NUL-terminated string
    // that outlives the call, and the `&str` is used only within it.
    let name = match unsafe { c_str_to_str(name) } {
        Ok(s) => s,
        Err(status) => return status,
    };
    let opened = shm_names(name).and_then(|(ring_name, store_name)| {
        let started = Instant::now();
        let mut backoff = Backoff::new(Some(OPEN_WAIT));
        loop {
            let last = match PulseRing::open_existing(&ring_name) {
                Ok(ring) => match EnvelopeStore::open_existing(&store_name) {
                    Ok(store) => {
                        // Resume where the reader last reported: zero on a
                        // new ring.
                        let next = ring.read_cursor_position();
                        return Ok(Ends {
                            window: 0,
                            ring,
                            store,
                            writer: false,
                            next,
                            origin: [0; 16],
                        });
                    }
                    Err(e) => format!("store {store_name}: {e}"),
                },
                Err(e) => format!("ring {ring_name}: {e}"),
            };
            if !backoff.step() {
                return Err(ChannelError::OpenTimedOut {
                    waited: started.elapsed(),
                    last,
                });
            }
        }
    });
    match opened {
        Ok(ends) => {
            // SAFETY: the caller asserted `out` is a writable slot.
            unsafe { *out = Box::into_raw(Box::new(pms_channel { ends })) };
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => e.report(&format!("pms_channel_open '{name}'")),
    }
}

/// Send one message of one frame, the `len` bytes at `data`, waiting up to
/// 5 seconds (the Python binding's default) while the reader has
/// `min(capacity, store_slots)` messages unread. A Python reader receives
/// it as a list of one `bytes`. Writer end only.
///
/// Returns `PMS_ERR_ENVELOPE_TOO_LARGE` for more than
/// `pms_channel_max_len()` bytes and `PMS_ERR_TIMEOUT` when the reader
/// leaves no room in time, with nothing sent in either case;
/// `PMS_ERR_INVALID_ARG` for a NULL handle, NULL `data` with a non-zero
/// `len`, or the reader end.
///
/// # Safety
/// `ch` must be a live handle from `pms_channel_create`. `data` must point
/// to `len` readable bytes, or be NULL with `len == 0`.
#[no_mangle]
pub unsafe extern "C" fn pms_channel_send(
    ch: *mut pms_channel,
    data: *const c_uchar,
    len: usize,
) -> pms_status {
    if ch.is_null() || (data.is_null() && len > 0) {
        set_last_error("pms_channel_send: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: `ch` was checked non-null; the caller asserts it is a live
    // handle no other thread uses during this call.
    let ends = unsafe { &mut (*ch).ends };
    if !ends.writer {
        set_last_error("pms_channel_send: on the reader end");
        return pms_status::PmsErrInvalidArg;
    }
    let frame: &[u8] = if len == 0 {
        &[]
    } else {
        // SAFETY: the caller asserts `data` points to `len` readable bytes.
        unsafe { std::slice::from_raw_parts(data, len) }
    };
    match ends.send(frame, SEND_WAIT) {
        Ok(()) => {
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => e.report("pms_channel_send"),
    }
}

/// Receive the next message into `buf`, waiting up to `timeout_ms`
/// milliseconds: 0 returns at once when none is waiting, and
/// `PMS_CHANNEL_WAIT_FOREVER` waits without limit. On `PMS_OK`, `*out_len`
/// is the message's length and the first `*out_len` bytes of `buf` are the
/// message. Reader end only.
///
/// A message is one frame, as `pms_channel_send` sends and as a Python
/// writer's `send` of one `bytes` object sends. Returns:
///
/// - `PMS_ERR_TIMEOUT` when no message came in time;
/// - `PMS_ERR_CLOSED` once the writer has closed the channel and every
///   message it sent has been read;
/// - `PMS_ERR_BUFFER_TOO_SMALL` for a message longer than `cap`: `*out_len`
///   is its length and it stays unread, so a call with that much room
///   receives it (`buf` may be NULL with `cap == 0`, to learn the length);
/// - `PMS_ERR_DECODE` for a message of more or fewer than one frame, which
///   only a Python writer sends (a list of frames): it is consumed, and
///   `pms_last_error` gives its frame count;
/// - `PMS_ERR_INTERNAL` when the ring or the store lost a message, which a
///   channel with one writer and one reader never does;
/// - `PMS_ERR_INVALID_ARG` for a NULL handle or `out_len`, NULL `buf` with
///   a non-zero `cap`, or the writer end.
///
/// # Safety
/// `ch` must be a live handle from `pms_channel_open`. `buf` must point to
/// `cap` writable bytes, or be NULL with `cap == 0`. `out_len` must point
/// to writable memory for one length.
#[no_mangle]
pub unsafe extern "C" fn pms_channel_recv(
    ch: *mut pms_channel,
    buf: *mut c_uchar,
    cap: usize,
    out_len: *mut usize,
    timeout_ms: u32,
) -> pms_status {
    if ch.is_null() || out_len.is_null() || (buf.is_null() && cap > 0) {
        set_last_error("pms_channel_recv: NULL argument");
        return pms_status::PmsErrInvalidArg;
    }
    // SAFETY: `ch` was checked non-null; the caller asserts it is a live
    // handle no other thread uses during this call.
    let ends = unsafe { &mut (*ch).ends };
    if ends.writer {
        set_last_error("pms_channel_recv: on the writer end");
        return pms_status::PmsErrInvalidArg;
    }
    let out: &mut [u8] = if cap == 0 {
        &mut []
    } else {
        // SAFETY: the caller asserts `buf` points to `cap` writable bytes
        // that nothing else accesses during this call.
        unsafe { std::slice::from_raw_parts_mut(buf, cap) }
    };
    let timeout = (timeout_ms != PMS_CHANNEL_WAIT_FOREVER)
        .then(|| Duration::from_millis(u64::from(timeout_ms)));
    match ends.recv_into(out, timeout) {
        Ok(len) => {
            // SAFETY: `out_len` was checked non-null and is writable per the
            // contract.
            unsafe { *out_len = len };
            clear_last_error();
            pms_status::PmsOk
        }
        Err(e) => {
            if let ChannelError::BufferTooSmall { needed, .. } = e {
                // SAFETY: as above.
                unsafe { *out_len = needed };
            }
            e.report("pms_channel_recv")
        }
    }
}

/// Messages sent and not yet read, as the writer counts them. 0 for NULL.
///
/// # Safety
/// `ch` must be NULL or a live channel handle.
#[no_mangle]
pub unsafe extern "C" fn pms_channel_pending(ch: *const pms_channel) -> u64 {
    if ch.is_null() {
        return 0;
    }
    // SAFETY: `ch` was checked non-null and is a live handle per the
    // contract; this only reads the ring's shared cursors.
    unsafe { &(*ch).ends }.pending()
}

/// The largest `len` `pms_channel_send` takes: the store's 65,536-byte
/// entry, less the envelope around a message and the 8 bytes of its frame
/// count and length (the Python binding's `Channel.MAX_PAYLOAD` less 8).
#[no_mangle]
pub extern "C" fn pms_channel_max_len() -> usize {
    max_frame()
}

/// Close and release a channel handle. The writer's close removes the
/// ring's and the store's names; a reader still attached reads what was
/// sent, then gets `PMS_ERR_CLOSED`. The reader's close only detaches.
/// NULL-safe.
///
/// # Safety
/// `ch` must either be NULL or a handle from `pms_channel_create` or
/// `pms_channel_open` not already closed.
#[no_mangle]
pub unsafe extern "C" fn pms_channel_close(ch: *mut pms_channel) {
    if ch.is_null() {
        return;
    }
    // SAFETY: the caller asserts `ch` is a live handle; the Box is rebuilt
    // and dropped, which unlinks the writer's names.
    drop(unsafe { Box::from_raw(ch) });
}

// ─────────────────────────── helpers ─────────────────────────────────

/// Convert a `*const c_char` into a Rust `&str`, returning the
/// appropriate `pms_status` if the input is NULL or not valid UTF-8.
///
/// # Safety
/// `p` must be NULL or point to a NUL-terminated string that stays valid,
/// and unchanged, for as long as the returned `&str` is used.
unsafe fn c_str_to_str<'a>(p: *const c_char) -> Result<&'a str, pms_status> {
    if p.is_null() {
        set_last_error("NULL string argument");
        return Err(pms_status::PmsErrInvalidArg);
    }
    // SAFETY: `p` is not NULL, and this function's contract makes it a
    // NUL-terminated string that outlives the returned borrow.
    let cstr = unsafe { CStr::from_ptr(p) };
    cstr.to_str().map_err(|e| {
        set_last_error(format!("invalid UTF-8 string: {e}"));
        pms_status::PmsErrInvalidString
    })
}

/// Write `s` as a NUL-terminated string into a caller-owned buffer of
/// `len` bytes. Truncates if necessary; always NUL-terminates if
/// `len > 0`. No-op if `len == 0`.
///
/// # Safety
/// `out` must be either NULL with `len == 0`, or point to `len`
/// writable bytes.
unsafe fn write_str_to_c_buf(s: &str, out: *mut c_char, len: usize) {
    if len == 0 {
        return;
    }
    let bytes = s.as_bytes();
    let n = bytes.len().min(len.saturating_sub(1));
    // SAFETY: caller asserts `out` points to `len` writable bytes;
    // `n < len` so `out.add(n)` is in-bounds for the NUL terminator.
    unsafe {
        ptr::copy_nonoverlapping(bytes.as_ptr(), out as *mut u8, n);
        *out.add(n) = 0;
    }
}

fn map_sender_err(e: &RustSenderError) -> pms_status {
    match e {
        RustSenderError::Io(_) => pms_status::PmsErrIo,
        RustSenderError::Encode(_) => pms_status::PmsErrEnvelopeTooLarge,
        RustSenderError::NoDestination => pms_status::PmsErrNotConnected,
        _ => pms_status::PmsErrInternal,
    }
}
